select *, sum(quantity) over (partition by product_id, order_id order by quantity, id rows between unbounded preceding and current row) as running_sum_quantity, avg(quantity) over (partition by product_id, order_id order by quantity, id rows between unbounded preceding and current row) as running_avg_quantity, max(quantity) over (partition by product_id, order_id order by quantity, id rows between unbounded preceding and current row) as running_max_quantity, count(quantity) over (partition by product_id, order_id order by quantity, id rows between unbounded preceding and current row) as running_count_quantity, last_value(quantity, true) over (partition by order_id, product_id order by quantity, id rows between unbounded preceding and current row) as last_known_quantity from order_items where unit_price < 130;
